def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors=set(v for row in grid for v in row)-{bg}
    def longest(color, vertical):
        best=run=0
        if vertical:
            for c in range(w):
                run=0
                for r in range(h): run=run+1 if grid[r][c]==color else 0; best=max(best,run)
        else:
            for row in grid:
                run=0
                for x in row: run=run+1 if x==color else 0; best=max(best,run)
        return best
    template=next((x for x in colors if longest(x,False)>=3 and longest(x,True)>=3),None)
    out=[row[:] for row in grid]
    if template is None: return out
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or color==template: continue
            # recolor compact straight objects matching the template's line orientation
            if c+1<w and grid[r][c+1]==color and (c==0 or grid[r][c-1]!=color) and (c+2==w or grid[r][c+2]!=color):
                out[r][c]=out[r][c+1]=template
            if r+1<h and grid[r+1][c]==color and (r==0 or grid[r-1][c]!=color) and (r+2==h or grid[r+2][c]!=color):
                out[r][c]=out[r+1][c]=template
    return out

